diff --git a/pegainfer-qwen3/src/config.rs b/pegainfer-qwen3/src/config.rs
index 3a84e400..9251b650 100644
--- a/pegainfer-qwen3/src/config.rs
+++ b/pegainfer-qwen3/src/config.rs
@@ -277,8 +277,7 @@ struct RawDFlashConfig {
 ///  A single-layer (`midlayer`) head whose attention takes
 /// `2 * hidden_size` inputs (concatenated `[norm(embed), norm(fused_hidden)]`),
 /// has no QK-norm, reuses the target's `embed_tokens`, and predicts over a
-/// reduced `draft_vocab_size` remapped to the full vocab via `d2t`/`t2d`.
-#[allow(dead_code)]
+/// reduced `draft_vocab_size` remapped to the full vocab via `d2t`.
 #[derive(Clone, Debug, Deserialize)]
 pub(crate) struct Eagle3Config {
     pub(crate) hidden_size: usize,
diff --git a/pegainfer-qwen3/src/eagle3.rs b/pegainfer-qwen3/src/eagle3.rs
index 6c32ba66..d05010dd 100644
--- a/pegainfer-qwen3/src/eagle3.rs
+++ b/pegainfer-qwen3/src/eagle3.rs
@@ -1,5 +1,4 @@
 // EAGLE-3 drafter (e.g. `AngelSlim/Qwen3-4B_eagle3`).
-#![allow(dead_code)]

 use anyhow::Result;
 use pegainfer_core::tensor::DeviceMatrix;
@@ -7,18 +6,23 @@ use pegainfer_core::tensor::DeviceVec;

 use crate::config::Eagle3Config;

+mod forward;
 mod loading;
 mod reservation;

-// Wired into the KV budget by the forward-pass PR; kept here as the skeleton lands.
-#[allow(unused_imports)]
+pub(crate) use forward::Eagle3RequestState;
+pub(crate) use forward::Eagle3Scratch;
 pub(crate) use reservation::Eagle3MemoryReservation;

 /// Number of tokens the EAGLE-3 chain drafts per speculative round (γ; the verify
 /// span is `EAGLE3_CHAIN_LENGTH + 1`: the current token plus γ drafts). v1 is a
-/// fixed top-1 **chain** — *not* a tree. γ=3 is the measured chain optimum on a Qwen3-4B GSM8K A/B (RTX 5070 Ti)
+/// fixed top-1 **chain** — *not* a tree.
 pub(crate) const EAGLE3_CHAIN_LENGTH: usize = 3;

+/// Requests one EAGLE-3 draft round serves. v1 drafts through a single-token
+/// scratch, so the scheduler plain-decodes any larger batch.
+pub(crate) const EAGLE3_MAX_BATCH: usize = 1;
+
 /// The three *target* layers (low/mid/high) whose **post-layer** hidden states
 /// EAGLE-3 captures and fuses via `fc`.
 ///
@@ -82,9 +86,6 @@ pub(crate) struct Eagle3DraftModel {
     /// Draft→target vocab offset map: `target_id = draft_id + d2t[draft_id]`.
     /// Length `draft_vocab_size`. Host-resident (small lookup, not a GEMM input).
     pub(crate) d2t: Vec<i64>,
-    /// Target→draft presence mask: `t2d[target_id]` is true iff that target token
-    /// exists in the draft vocab. Length `vocab_size`.
-    pub(crate) t2d: Vec<bool>,
     pub(crate) cos_cache: DeviceVec,
     pub(crate) sin_cache: DeviceVec,
 }
diff --git a/pegainfer-qwen3/src/lib.rs b/pegainfer-qwen3/src/lib.rs
index 0fc03054..2f69c0a8 100644
--- a/pegainfer-qwen3/src/lib.rs
+++ b/pegainfer-qwen3/src/lib.rs
@@ -40,6 +40,8 @@ pub use weights::DEFAULT_KV_CACHE_MEMORY_MARGIN_BYTES;
 pub use weights::DEFAULT_KV_PAGE_SIZE;
 pub use weights::Qwen3MemoryOptions;

+use crate::speculative::DraftModel;
+
 #[derive(Clone, Copy, Debug, Eq, PartialEq)]
 pub struct Qwen3LoraOptions {
     max_loras: usize,
@@ -253,6 +255,10 @@ pub struct Qwen3LaunchOptions {
     /// `Some` enables DFlash speculative decoding with this drafter model.
     /// Single-GPU only and mutually exclusive with LoRA and KV offload.
     pub dflash_draft_model_path: Option<PathBuf>,
+    /// `Some` enables EAGLE-3 speculative decoding with this drafter model:
+    /// greedy requests draft while they are the only active request. Same
+    /// limits as DFlash, and mutually exclusive with it.
+    pub eagle3_draft_model_path: Option<PathBuf>,
 }

 /// Start the Qwen3 engine from server-facing [`Qwen3LaunchOptions`].
@@ -307,14 +313,24 @@ pub fn launch(model_path: &Path, options: Qwen3LaunchOptions) -> Result<Engine>
         options.tp_size == 1 || matches!(options.decode_overlap, DecodeOverlap::Off),
         "decode-overlap is unsupported under tensor parallelism"
     );
+    let draft = match (
+        options.dflash_draft_model_path.as_deref(),
+        options.eagle3_draft_model_path.as_deref(),
+    ) {
+        (Some(_), Some(_)) => {
+            anyhow::bail!("DFlash and EAGLE-3 drafters cannot be loaded together")
+        }
+        (Some(path), None) => Some(DraftModel::DFlash(draft_path(path)?)),
+        (None, Some(path)) => Some(DraftModel::Eagle3(draft_path(path)?)),
+        (None, None) => None,
+    };
     anyhow::ensure!(
-        !(options.dflash_draft_model_path.is_some() && options.lora.is_some()),
-        "DFlash speculative decoding cannot be combined with LoRA serving"
+        !(draft.is_some() && options.lora.is_some()),
+        "speculative decoding cannot be combined with LoRA serving"
     );
     anyhow::ensure!(
-        options.dflash_draft_model_path.is_none()
-            || matches!(options.decode_overlap, DecodeOverlap::Off),
-        "DFlash speculative decoding cannot be combined with decode overlap \
+        draft.is_none() || matches!(options.decode_overlap, DecodeOverlap::Off),
+        "speculative decoding cannot be combined with decode overlap \
          (--decode-overlap): the speculative path never takes the unified overlap \
          route, so the overlap streams would only waste VRAM the drafter needs"
     );
@@ -345,12 +361,17 @@ pub fn launch(model_path: &Path, options: Qwen3LaunchOptions) -> Result<Engine>
             options.memory,
             options.decode_overlap,
             options.batch_invariant,
-            options.dflash_draft_model_path.as_deref(),
+            draft,
             options.dump_graph_png.as_deref(),
         ),
     }
 }

+fn draft_path(path: &Path) -> Result<&str> {
+    path.to_str()
+        .ok_or_else(|| anyhow::anyhow!("draft model path must be valid UTF-8"))
+}
+
 pub fn start_engine(model_path: &Path, options: EngineLoadOptions) -> Result<Engine> {
     start_engine_with_offload(
         model_path,
@@ -398,7 +419,10 @@ pub fn start_engine_with_offload(
         memory_options,
         decode_overlap,
         batch_invariant,
-        dflash_draft_model_path,
+        dflash_draft_model_path
+            .map(draft_path)
+            .transpose()?
+            .map(DraftModel::DFlash),
         None,
     )
 }
@@ -413,7 +437,7 @@ fn start_engine_with_offload_inner(
     memory_options: Qwen3MemoryOptions,
     decode_overlap: DecodeOverlap,
     batch_invariant: bool,
-    dflash_draft_model_path: Option<&Path>,
+    draft: Option<DraftModel<'_>>,
     dump_graph_png: Option<&Path>,
 ) -> Result<Engine> {
     crate::spec_env::validate()?;
@@ -431,17 +455,11 @@ fn start_engine_with_offload_inner(
             decode_overlap,
             no_prefix_cache,
             offload_options.enabled,
-            dflash_draft_model_path.is_some(),
+            draft.is_some(),
             device_ordinals.len(),
         )?;
     }
     apply_batch_invariant_policy(batch_invariant);
-    let dflash_draft_model_path = dflash_draft_model_path
-        .map(|path| {
-            path.to_str()
-                .ok_or_else(|| anyhow::anyhow!("DFlash draft model path must be valid UTF-8"))
-        })
-        .transpose()?;
     frontend_adapter::start_qwen3(
         model_path,
         enable_cuda_graph,
@@ -452,7 +470,7 @@ fn start_engine_with_offload_inner(
         max_prefill_tokens,
         memory_options,
         decode_overlap,
-        dflash_draft_model_path,
+        draft,
         dump_graph_png,
     )
 }
@@ -519,7 +537,7 @@ fn ensure_batch_invariant_supported(
     decode_overlap: DecodeOverlap,
     no_prefix_cache: bool,
     offload: bool,
-    dflash: bool,
+    speculative: bool,
     world_size: usize,
 ) -> Result<()> {
     if !matches!(decode_overlap, DecodeOverlap::Off) {
@@ -539,9 +557,9 @@ fn ensure_batch_invariant_supported(
             "--batch-invariant is not supported with tensor parallelism: world_size={world_size} has unverified cross-rank reduction order"
         );
     }
-    if dflash {
+    if speculative {
         anyhow::bail!(
-            "--batch-invariant is not supported with DFlash speculative decoding: the decode-GEMM \
+            "--batch-invariant is not supported with speculative decoding: the decode-GEMM \
              pin warms and self-checks only the base projections, so the drafter's fc/MLP GEMMs \
              are not pinned and would bail at the GEMM boundary under Pin"
         );

