use anyhow::Context;
use anyhow::Result;
use cudarc::driver::CudaSlice;
use half::bf16;
use pegainfer_core::ops;
use pegainfer_core::tensor::DeviceContext;
use pegainfer_core::tensor::HiddenStates;
use pegainfer_kernels::ops::argmax_batch_bf16_split_partials_len;
use pegainfer_kernels::ops::argmax_bf16_split_into;

use super::Eagle3DraftModel;
use crate::weights::Qwen3Model;

/// Draft slots available at `cached_len`, capped to `requested_k`.
///
/// The constraint is `cached_len + k + 1 <= max_cache_len`, where +1 is the bonus token
/// generated by speculative decoding
fn chain_capacity(cached_len: usize, max_cache_len: usize, requested_k: usize) -> usize {
    let draftable = max_cache_len.saturating_sub(cached_len).saturating_sub(1);
    requested_k.min(draftable)
}

/// Per-request state the EAGLE-3 draft carries *between* forwards.
/// To record kv cache size for draft memory allocation
pub(crate) struct Eagle3RequestState {
    k: HiddenStates,
    v: HiddenStates,
    cached_len: usize,
    max_cache_len: usize,
    /// Boundary target feature `[3 * hidden, 1]` at the last committed position
    last_aux_hidden_states: Option<HiddenStates>,
}

/// Single-token draft scratch (`seq_len == 1` everywhere). v1 runs one request,
/// one token at a time — batching the draft chain is a follow-up
pub(crate) struct Eagle3Scratch {
    // Device argmax over `logits`: only the picked id crosses to the host.
    argmax_partial_values: CudaSlice<f32>,
    argmax_partial_indices: CudaSlice<i32>,
    argmax_value: CudaSlice<bf16>,
    argmax_index: CudaSlice<i32>,
    token_id_d: CudaSlice<u32>,
    embed: HiddenStates,         // [hidden, 1]
    hidden: HiddenStates,        // [hidden, 1] residual stream
    normed_embed: HiddenStates,  // [hidden, 1]
    normed_hidden: HiddenStates, // [hidden, 1]
    attn_input: HiddenStates,    // [2 * hidden, 1]
    q: HiddenStates,             // [q_dim, 1]
    k: HiddenStates,             // [kv_dim, 1]
    v: HiddenStates,             // [kv_dim, 1]
    attn_out: HiddenStates,      // [q_dim, 1]
    o: HiddenStates,             // [hidden, 1]
    normed_post: HiddenStates,   // [hidden, 1]
    gate: HiddenStates,          // [inter, 1]
    up: HiddenStates,            // [inter, 1]
    act: HiddenStates,           // [inter, 1]
    mlp_out: HiddenStates,       // [hidden, 1]
    normed_final: HiddenStates,  // [hidden, 1]
    logits: HiddenStates,        // [draft_vocab, 1]
}

impl Eagle3DraftModel {
    fn q_dim(&self) -> usize {
        self.midlayer.q_dim
    }

    fn kv_dim(&self) -> usize {
        self.midlayer.kv_dim
    }

    /// Allocate the single-layer K/V cache for one request. `max_cache_len` bounds
    /// the total drafted+committed positions and must fit the rope cache.
    pub(crate) fn new_request_state(
        &self,
        ctx: &DeviceContext,
        max_cache_len: usize,
    ) -> Result<Eagle3RequestState> {
        anyhow::ensure!(
            max_cache_len > 0 && max_cache_len <= self.config.max_position_embeddings,
            "EAGLE-3 request cache length {} must be in 1..={}",
================
//! Worker-side EAGLE-3 draft lane: the draft model plus per-request draft state.
//!
//! Like the DFlash lane it lives on the worker thread next to the target model,
//! because the drafter reads the target's embeddings and the hidden states the
//! target captures at prefill and verify. Those hidden states stay private to
//! this lane; the draft/verify boundary is a pure token span.

use std::collections::HashMap;

use anyhow::Result;
use pegainfer_core::tensor::HiddenStates;

use super::DraftMeta;
use super::LocalQwen3Lane;
use super::PrefillStepItem;
use super::RequestId;
use super::dflash_prefill::prefill_capture_supported;
use crate::eagle3::EAGLE3_CHAIN_LENGTH;
use crate::eagle3::EAGLE3_MAX_BATCH;
use crate::eagle3::Eagle3DraftModel;
use crate::eagle3::Eagle3RequestState;
use crate::eagle3::Eagle3Scratch;
use crate::eagle3::aux_hidden_state_layers;
use crate::speculative::DraftRequestResult;
use crate::speculative::DraftResult;
use crate::speculative::DraftStepItem;
use crate::speculative::VerifyRequestResult;
use crate::speculative::VerifyStepItem;

pub(super) struct Eagle3LaneState {
    model: Eagle3DraftModel,
    requests: HashMap<RequestId, Eagle3RequestState>,
    scratch: Eagle3Scratch,
    /// Target layers whose post-layer hidden states feed the drafter's `fc`.
    aux_layers: [usize; 3],
}

impl Eagle3LaneState {
    pub(super) fn aux_layers(&self) -> &[usize] {
        &self.aux_layers
    }
}

/// Whether a prefill step seeds the drafter for `req`. v1 is greedy only, and
/// `prefill_prompt` needs the whole prompt in one chunk; anything else decodes
/// without speculation.
